		    name:"RELIC EXTRACTION", icon:"✓", kind:"normal", pos:"center", duration:1500, status:"COMPLETE",
		    content:`<div class="wp-meter"><span class="big">47</span><span class="unit">/ 47 NODES SUCCESS</span></div><div class="wp-div"></div>${kvRows([["TOTAL","47","ok"],["SUCCESS","47","ok"],["ROLLBACK","2","warn"],["ELAPSED","T-00:01:28"]])}<div class="wp-note">所有NODE固件OVERWRITE完成，已切换至 RELIC 安全RELIC CORE。</div><div class="wp-btns"><button class="wp-btn-b">VIEW LOG</button><button class="wp-btn-b primary">PROCEED</button></div>`
